mapper.select:
SELECT c.exam_candidate_id AS examCandidateId, c.assessment_execution_id AS assessmentExecutionId, x.exam_id AS examId, c.user_id AS userId, COALESCE(JSON_UNQUOTE(JSON_EXTRACT(c.candidate_profile_snapshot_json, '$.userName')), u.user_name) AS learnerName, COALESCE(JSON_UNQUOTE(JSON_EXTRACT(c.candidate_profile_snapshot_json, '$.userCode')), u.user_code) AS learnerCode, c.organization_id AS learnerOrganizationId, COALESCE(JSON_UNQUOTE(JSON_EXTRACT(c.candidate_profile_snapshot_json, '$.organizationName')), org.org_name) AS learnerOrganizationName, u.dept_id AS deptId, d.dept_name AS deptName, x.source_type AS sourceType, c.candidate_status AS candidateStatus, c.attempt_count AS attemptCount, c.best_score AS bestScore, c.final_score AS finalScore, c.final_attempt_id AS finalAttemptId, c.result_published_time AS resultPublishedTime, c.result_effective_time AS resultEffectiveTime, c.version AS version FROM sts_exam_candidate c JOIN sts_assessment_execution x ON x.assessment_execution_id = c.assessment_execution_id AND x.deleted = 0 LEFT JOIN us_sys_user u ON u.user_id = c.user_id AND u.deleted = 0 LEFT JOIN us_sys_dept d ON d.dept_id = u.dept_id AND d.deleted = 0 LEFT JOIN sts_org_organization org ON org.organization_id = c.organization_id AND org.deleted = 0 WHERE c.deleted = 0 AND x.exam_id = #{examId}
AND c.candidate_status = #{query.candidateStatus}
AND ( COALESCE(JSON_UNQUOTE(JSON_EXTRACT(c.candidate_profile_snapshot_json, '$.userName')), u.user_name) LIKE CONCAT('%', #{query.learnerKeyword}, '%') OR COALESCE(JSON_UNQUOTE(JSON_EXTRACT(c.candidate_profile_snapshot_json, '$.userCode')), u.user_code) LIKE CONCAT('%', #{query.learnerKeyword}, '%') )
ORDER BY c.exam_candidate_id ASC
